local QuillCutterMaker = {}
local PRODUCTS = {
    iron_quill_cutter = { name = "Železni rezalec peres", ironCost = 3, woodCost = 2, leatherCost = 1, time = 4, cost = 145, prestige = 3, happiness = 2, description = "Železni rezalec za ostrenje pisalnih peres." },
    bronze_quill_cutter = { name = "Bronast rezalec peres", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 6, cost = 350, prestige = 5, happiness = 3, description = "Bronast rezalec za fino ostrenje peres." },
    silver_quill_cutter = { name = "Srebrni rezalec peres", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 10, cost = 850, prestige = 10, happiness = 4, description = "Srebrni rezalec za plemiške pisarje." },
    gilded_quill_cutter = { name = "Pozlačeni rezalec peres", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 14, cost = 1820, prestige = 19, happiness = 5, description = "Pozlačeni rezalec za dvorne pisarje." },
    jewel_set_quill_cutter = { name = "Draguljasti rezalec peres", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 18, cost = 3950, prestige = 35, happiness = 7, description = "Draguljasti rezalec za kraljevske pisarje." },
    royal_sovereign_quill_cutter = { name = "Kraljevski suvereni rezalec peres", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 25, cost = 8500, prestige = 67, happiness = 13, description = "Suvereni rezalec z biseri za krono." },
}
local BUILDINGS = {
    quillcutter_workshop = { name = "Rezalna delavnica", cost = { gold = 305, wood = 180, stone = 125, iron = 7 }, upkeep = 5, qualityBonus = 5 },
    quillcutter_house = { name = "Rezalna hiša", cost = { gold = 1135, wood = 360, stone = 260, silver = 6, iron = 7 }, upkeep = 24, qualityBonus = 18 },
    master_quillcutter_atelier = { name = "Mojstrski rezalni atelje", cost = { gold = 2880, wood = 420, stone = 500, silver = 33, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    sovereign_quillcutter_palace = { name = "Suverena rezalna palača", cost = { gold = 12480, wood = 645, stone = 805, gold = 80, jewel = 18 }, upkeep = 246, qualityBonus = 55, prestigeBonus = 50 },
}
QuillCutterMaker.ironStock = 14; QuillCutterMaker.bronzeStock = 12; QuillCutterMaker.woodStock = 14; QuillCutterMaker.leatherStock = 8; QuillCutterMaker.silverStock = 8; QuillCutterMaker.goldStock = 6; QuillCutterMaker.jewelStock = 4; QuillCutterMaker.pearlStock = 4
QuillCutterMaker.productStock = {}; QuillCutterMaker.buildings = {}; QuillCutterMaker.maker = nil; QuillCutterMaker.activeMaking = {}; QuillCutterMaker.totalProducts = 0; QuillCutterMaker.dayTimer = 0
function QuillCutterMaker.init() QuillCutterMaker.ironStock=14; QuillCutterMaker.bronzeStock=12; QuillCutterMaker.woodStock=14; QuillCutterMaker.leatherStock=8; QuillCutterMaker.silverStock=8; QuillCutterMaker.goldStock=6; QuillCutterMaker.jewelStock=4; QuillCutterMaker.pearlStock=4; QuillCutterMaker.productStock={}; QuillCutterMaker.buildings={}; QuillCutterMaker.maker=nil; QuillCutterMaker.activeMaking={}; QuillCutterMaker.totalProducts=0; QuillCutterMaker.dayTimer=0; print("[QuillCutterMaker] Royal Quill Cutter Maker System initialized (6 products, 4 buildings)") end
function QuillCutterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; QuillCutterMaker.maker={name=n or ("Rezar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezar najet: %s (spretnost: %d)",QuillCutterMaker.maker.name,s),"success") end; return true end
function QuillCutterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function QuillCutterMaker.build(id) local ok,e=QuillCutterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(QuillCutterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function QuillCutterMaker.getQualityBonus() local b=0; for _,bd in ipairs(QuillCutterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function QuillCutterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and QuillCutterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and QuillCutterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and QuillCutterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and QuillCutterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and QuillCutterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and QuillCutterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and QuillCutterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and QuillCutterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #QuillCutterMaker.buildings==0 then return false,"Potrebna rezalna delavnica" end; if not QuillCutterMaker.maker then return false,"Potreben rezar" end; return true end
function QuillCutterMaker.make(pt,qty) qty=qty or 1; local ok,e=QuillCutterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then QuillCutterMaker.ironStock=QuillCutterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then QuillCutterMaker.bronzeStock=QuillCutterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then QuillCutterMaker.woodStock=QuillCutterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then QuillCutterMaker.leatherStock=QuillCutterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then QuillCutterMaker.silverStock=QuillCutterMaker.silverStock-d.silverCost*qty end; if d.goldCost then QuillCutterMaker.goldStock=QuillCutterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then QuillCutterMaker.jewelStock=QuillCutterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then QuillCutterMaker.pearlStock=QuillCutterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if QuillCutterMaker.maker then t=math.max(1,t-math.floor(QuillCutterMaker.maker.skill/13)) end; table.insert(QuillCutterMaker.activeMaking,{id="quillcutter_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function QuillCutterMaker.completeMaking(m) local q=1.0+(QuillCutterMaker.getQualityBonus()/100); if QuillCutterMaker.maker then q=q+(QuillCutterMaker.maker.skill/140) end; q=math.min(2.5,q); QuillCutterMaker.productStock[m.productType]=(QuillCutterMaker.productStock[m.productType] or 0)+m.quantity; QuillCutterMaker.totalProducts=QuillCutterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if QuillCutterMaker.maker then QuillCutterMaker.maker.itemsMade=QuillCutterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then QuillCutterMaker.maker.skill=math.min(100,QuillCutterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"quillcutter.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function QuillCutterMaker.update(dt) if not _G.state then return end; QuillCutterMaker.dayTimer=QuillCutterMaker.dayTimer+dt; if QuillCutterMaker.dayTimer>=30 then QuillCutterMaker.dayTimer=0; for i=#QuillCutterMaker.activeMaking,1,-1 do local m=QuillCutterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then QuillCutterMaker.completeMaking(m); table.remove(QuillCutterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(QuillCutterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if QuillCutterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function QuillCutterMaker.getStats() return {ironStock=QuillCutterMaker.ironStock,bronzeStock=QuillCutterMaker.bronzeStock,woodStock=QuillCutterMaker.woodStock,leatherStock=QuillCutterMaker.leatherStock,silverStock=QuillCutterMaker.silverStock,goldStock=QuillCutterMaker.goldStock,jewelStock=QuillCutterMaker.jewelStock,pearlStock=QuillCutterMaker.pearlStock,productStock=QuillCutterMaker.productStock,numBuildings=#QuillCutterMaker.buildings,hasMaker=QuillCutterMaker.maker~=nil,makerName=QuillCutterMaker.maker and QuillCutterMaker.maker.name or "—",makerSkill=QuillCutterMaker.maker and QuillCutterMaker.maker.skill or 0,activeMaking=#QuillCutterMaker.activeMaking,totalProducts=QuillCutterMaker.totalProducts} end
return QuillCutterMaker
